window.__saqPaperQuestions("2017-1-nsw",[{"number":1,"title":"","stemText":"A 65 year old man has presented to your regional ED with acute onset SOB and chest pain.\nHis pain is severe and radiates to his back.\n\nVital signs:\n\nHR\n125 bpm\n\nBP\n98/52 mmHg\n\nRR\n22 bpm\n\nSaO2 RA\n96%\n\nTemp\n37.2 deg C","parts":[{"id":"a","label":"Part A","prompt":"List 4 important features on this ECG (4 marks)\nA 12 LEAD ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 3"},{"id":"b","label":"Part B","prompt":"List 4 features on a CXR that would raise your suspicion of acute aortic dissection (4\nmarks)"},{"id":"c","label":"Part C","prompt":"What features on bedside US would help differentiate acute MI from aortic dissection as the cause of shock (4 marks)"},{"id":"d","label":"Part D","prompt":"CT imaging is unavailable. Given the patient’s history and clinical examination you treat him for an acute aortic dissection. List 6 management steps (6 marks)"},{"id":"e","label":"Part E","prompt":"List a classification of aortic dissections (2 marks)"}],"propPages":["asset:imga831b93a3cae6ea95a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Inferior STEMI</div><div class=\"answer-line\">o STE lead  III</div><div class=\"answer-line\">o Hyperacute T wave leads II, III, aVF</div><div class=\"answer-line\">o Reciprocal changes aVL STD and TWI</div><div class=\"answer-line\">• Possible RVMI</div><div class=\"answer-line\">o III&gt;II</div><div class=\"answer-line\">o V2 ST depression</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">List 4 features on a CXR that would raise your suspicion of acute aortic dissection (4</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">• Widening of the superior mediastinum</div><div class=\"answer-line\">• Dilatation of the aortic arch</div><div class=\"answer-line\">• Change in the configuration of the aorta on successive CXR</div><div class=\"answer-line\">• Obliteration of aortic knob</div><div class=\"answer-line\">• Double density of aorta (suggesting true and false lumen)</div><div class=\"answer-line\">• Localised prominence along aortic contour</div><div class=\"answer-line\">• Disparity of calibre between descending and ascending aorta</div><div class=\"answer-line\">• “Calcium Sign” (&gt;6mm between intimal calcium and shadow of outer aortic wall)</div><div class=\"answer-line\">• Displacement of trachea to right</div><div class=\"answer-line\">• Distortion of left main stem bronchus</div><div class=\"answer-line\">• Pleural effusion</div><div class=\"answer-line\">• Cardiomegaly</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">What features on bedside US would help differentiate acute MI from aortic dissection as</div><div class=\"answer-line\">the cause of shock (4 marks)</div><div class=\"answer-line\">• Myocardial infarction (inferior/right ventricle)</div><div class=\"answer-line\">o Regional wall motion abnormality/hypokinesis</div><div class=\"answer-line\">• Dissection</div><div class=\"answer-line\">o Pericardial effusion + right vent collapse + dilated IVC (Pericardial</div><div class=\"answer-line\">tamponade)</div><div class=\"answer-line\">o AV incompetence/regurg</div><div class=\"answer-line\">o Intimal flap (sternal notch view)</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">CT imaging is unavailable. Given the patient’s history and clinical examination you treat</div><div class=\"answer-line\">him for an acute aortic dissection. List 6 management steps (6 marks)</div><div class=\"answer-line\">• Manage in resuscitation bay</div><div class=\"answer-line\">• x2 IVC access; bloods including group and hold</div><div class=\"answer-line\">• IV analgesia (opiate: fentanyl/morphine)</div><div class=\"answer-line\">• IV rate control (beta-blocker: metoprolol, esmolol); aim for rate 60</div><div class=\"answer-line\">• IV BP control (GTN, SNIP, hydralazine); aim for SBP &lt;140</div><div class=\"answer-line\">• Arterial line for invasive BP monitoring</div><div class=\"answer-line\">• Urgent transfer to CTSx centre for CT +/- OT</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">• Stanford</div><div class=\"answer-line\">o A: Ascending aorta with or without descending</div><div class=\"answer-line\">o B: Descending aorta only (distal to origin of left subclavian)</div><div class=\"answer-line\">• De Bakey</div><div class=\"answer-line\">o I Ascending and descending</div><div class=\"answer-line\">o II Ascending only</div><div class=\"answer-line\">o III Descending only</div><div class=\"answer-line\">▪ A: thoracic</div><div class=\"answer-line\">▪ B: extends into abdominal aorta</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 40 year old woman presents with symptoms of a common peroneal nerve injury of her\nleft leg following an ankle sprain.","parts":[{"id":"a","label":"Part A","prompt":"Describe the sensory and motor disturbance features of a common peroneal nerve injury (4 marks)"},{"id":"b","label":"Part B","prompt":"Where is the commonest site of injury (1 mark)"},{"id":"c","label":"Part C","prompt":"List 4 general causes of common peroneal nerve injury other than high ankle sprain (4\nmarks)"},{"id":"d","label":"Part D","prompt":"How is this peripheral nerve lesion differentiated from an L5 radiculopathy (1 mark)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Describe the sensory and motor disturbance features of a common peroneal nerve</div><div class=\"answer-line\">injury (4 marks)</div><div class=\"answer-line\">• Sensory deficit</div><div class=\"answer-line\">o lateral leg below knee</div><div class=\"answer-line\">o dorsum foot</div><div class=\"answer-line\">• Motor deficit</div><div class=\"answer-line\">o dorsiflexion ankle (foot drop) and great toe</div><div class=\"answer-line\">o eversion foot</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• At the fibular head</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List 4 general causes of common peroneal nerve injury other than high ankle sprain (4</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">• Fracture fibula</div><div class=\"answer-line\">• Tight plaster leg involving knee</div><div class=\"answer-line\">• Regular wear of high knee boots</div><div class=\"answer-line\">• Prolonged coma or bed rest with pressure at knee</div><div class=\"answer-line\">• Pneumatic compression</div><div class=\"answer-line\">• Habitual leg crossing</div><div class=\"answer-line\">• Total knee arthroplasty</div><div class=\"answer-line\">• Proximal tibial osteotomy</div><div class=\"answer-line\">• Leg squatting/crossing</div><div class=\"answer-line\">• Endocrine/metabolic disorders: diabetes, alcoholism, thyrotoxicosis, vitamin B depletion</div><div class=\"answer-line\">• Others…</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Inversion and plantar flexion should be preserved</div><div class=\"answer-line\">• Decreased or absent ankle reflex in radiculopathy</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 27 year old male driver has been involved in a motor vehicle crash at 140kph. He was\ntaken to a rural base hospital and was intubated soon after arrival in ED. Current vital signs\nare BP 80/40 mmHg, P 140 bpm.\nA CHEST XRAY IS SHOWN IN THE PROPS BOOKLET, PAGE 4","parts":[{"id":"a","label":"Part A","prompt":"List 6 findings on his CXR (6 marks)"},{"id":"b","label":"Part B","prompt":"List 5 potential diagnoses in order of severity (5 marks)"},{"id":"c","label":"Part C","prompt":"List the next 3 investigations you would order/perform, in order of priority and provide\nyour reasoning (6 marks)"}],"propPages":["asset:img243ae10ed33639b535"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• ETT just above the level of his clavicles</div><div class=\"answer-line\">• NG tube in situ that migrates below the level of the right hemidiaphragm and curls</div><div class=\"answer-line\">around to the left above the level of the right hemidiaphragm</div><div class=\"answer-line\">• Deviation of the NG tube to the right</div><div class=\"answer-line\">• Elevation of the left hemidiaphragm</div><div class=\"answer-line\">• Fracture left scapula(subtle)</div><div class=\"answer-line\">• Left lung basal collapse/consolidation</div><div class=\"answer-line\">• Left apical capping</div><div class=\"answer-line\">• Widened mediastinum</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">• Aortic dissection/transection</div><div class=\"answer-line\">• Diaphragm rupture</div><div class=\"answer-line\">• Cardiac injury(blunt)</div><div class=\"answer-line\">• Lung injury-contusion/laceration</div><div class=\"answer-line\">• Spleen injury</div><div class=\"answer-line\">• Fractures- scapula, ribs</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List the next 3 investigations you would order/perform, in order of priority and provide</div><div class=\"answer-line\">your reasoning (6 marks)</div><div class=\"answer-line\">• EFAST</div><div class=\"answer-line\">o assess for pericardial tamponade, assess for Type A dissection and assess for</div><div class=\"answer-line\">abdominal FF/PTx/HTx</div><div class=\"answer-line\">• Bloods</div><div class=\"answer-line\">o FBC, G+H, coag - suspected haemorrhage and coagulopathy of trauma</div><div class=\"answer-line\">• CT pan scan</div><div class=\"answer-line\">o given mechanism to assess for aortic injury,  significant solid organ</div><div class=\"answer-line\">injury/abdominopelvic bleeding</div><div class=\"answer-line\">• Blood gas</div><div class=\"answer-line\">o assess for shock - BE, lactate and response to Rx</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"There have been a number of incidents in your emergency department Short Stay Unit where patients have unexpectedly deteriorated during their stay.","parts":[{"id":"a","label":"Part A","prompt":"Define the role of a Short Stay Unit (2 marks)"},{"id":"b","label":"Part B","prompt":"How would you develop a solution to this problem (4 marks)"},{"id":"c","label":"Part C","prompt":"You are tasked to develop exclusion criteria for your Short Stay Unit. List 5 criteria (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• To manage Emergency Medicine patients who would benefit from extended treatment</div><div class=\"answer-line\">and observation but have an expected length of stay of less than 24 hours.</div><div class=\"answer-line\">• Taken from Cameron Textbook of Adult Emergency Medicine 3rd Edition Section 27.2</div><div class=\"answer-line\">• 1 mark for providing extended care for Emergency Medicine patients</div><div class=\"answer-line\">• 1 mark for acknowledging an expected length of stay of 24 hour or less</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Gather information</div><div class=\"answer-line\">• Develop solution plan</div><div class=\"answer-line\">• Implement plan</div><div class=\"answer-line\">• Audit / Re-collect data</div><div class=\"answer-line\">• Note exact wording not essential but plan must include aspects of each of these</div><div class=\"answer-line\">domains to score maximum marks</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">You are tasked to develop exclusion criteria for your Short Stay Unit. List 5 criteria (5</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">• Patients who should be admitted to in-patient wards - complex medical or surgical</div><div class=\"answer-line\">problems</div><div class=\"answer-line\">• Multiple problems</div><div class=\"answer-line\">• Elderly patient</div><div class=\"answer-line\">• Paediatric patients</div><div class=\"answer-line\">• Patients without clear management plan / diagnosis</div><div class=\"answer-line\">• Patients with intensive nursing requirements</div><div class=\"answer-line\">• Risk to staff patients - psychotic, violent, forensic history</div><div class=\"answer-line\">Taken from Cameron Textbook of Adult Emergency Medicine 3rd Edition Section 26.6</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 28 year old male with a known history of ice abuse has been brought into your tertiary ED by ambulance having required pre-hospital sedation with intramuscular droperidol. Vital signs are:\n\nT\n38.4 deg C\n\nHR\n128 bpm\n\nBP\n158/80 mmHg\n\nRR\n18 bpm\n\nSaO2 100% on 6L via HM\n\nGCS\n9 (E2V2M5)","parts":[{"id":"a","label":"Part A","prompt":"Describe 5 possible causes of his presentation (5 marks)"},{"id":"b","label":"Part B","prompt":"List 5 investigations you would perform and provide your reasoning (5 marks)"},{"id":"c","label":"Part C","prompt":"The patient promptly suffers a grand mal seizure. Describe your initial management, including drug doses where appropriate (5 marks)"},{"id":"d","label":"Part D","prompt":"His Na+ level is 116 mmol/L. Outline the initial management of his hyponatraemia and\nplan for the next 24 hours (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Drug ingestion/withdrawal (serotonin or NM syndrome less likely) – sympathomimetics,</div><div class=\"answer-line\">anticholinergics, aspirin etc</div><div class=\"answer-line\">• Meningo-encephalitis</div><div class=\"answer-line\">• Post-ictal</div><div class=\"answer-line\">• Dyselectrolytaemia</div><div class=\"answer-line\">• Heat illness</div><div class=\"answer-line\">• Subarachnoid haemorrhage</div><div class=\"answer-line\">• Traumatic ICH</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">• Glucose – hypo/hyperglycaemia rapidly reversible</div><div class=\"answer-line\">• A/VBG – occult sepsis, hypercarbia, glucose, electrolytes</div><div class=\"answer-line\">• CTB – SAH/ICH/CVA (SOL)</div><div class=\"answer-line\">• Electrolyte panel (biochemistry ALF/ARF)</div><div class=\"answer-line\">• Blood ETOH/measured-calculated osmolarity</div><div class=\"answer-line\">• ECG – QT prolongation post droperidol</div><div class=\"answer-line\">• Consider LP after CTB – for infection/xanthachromia</div><div class=\"answer-line\">• Must provide an answer with reasoning to score one mark</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">The patient promptly suffers a grand mal seizure. Describe your initial management,</div><div class=\"answer-line\">including drug doses where appropriate (5 marks)</div><div class=\"answer-line\">• Midazolam 0.15mg/kg (possibly in two divided doses) +/- phenytoin/keppra (15-</div><div class=\"answer-line\">20mg/kg)</div><div class=\"answer-line\">• Manage airway, assess need for ETT and GA</div><div class=\"answer-line\">• Early antibiotics +/- anti-virals</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">His Na+ level is 116 mmol/L. Outline the initial management of his hyponatraemia and</div><div class=\"answer-line\">plan for the next 24 hours (4 marks)</div><div class=\"answer-line\">• Bolus 100 mls 3% HTS, repeat x 1 if remains altered mental state with airway threat,</div><div class=\"answer-line\">further seizure (and Na+ not climbed over 6mmol/L)</div><div class=\"answer-line\">• Aim total Na+ increase 6-12 mmol/24 hours (0.5-1.0 mmol/L/hr including bolus Rx); or</div><div class=\"answer-line\">calculate deficit and aim to replace half the deficit in appropriate timeframe</div><div class=\"answer-line\">• Will require HDU/ICU management</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"This question concerns ECG changes and acute treatment associated with potassium disorders.","parts":[{"id":"a","label":"Part A","prompt":"List 3 key ECG features of significant HYPOkalaemia (3 marks)"},{"id":"b","label":"Part B","prompt":"List 3 key ECG features of significant HYPERkalaemia (3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 treatment options for acute severe hyperkalaemia. For each, describe its\nmechanism of action and time course (9 marks) Treatment/Dose Mechanism of Action Onset & duration of effect"},{"id":"d","label":"Part D","prompt":"Briefly outline any concerns or issues related to using cation-exchange resins (calcium resonium) for the acute treatment of hyperkalaemia (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• QTc prolongation</div><div class=\"answer-line\">• Prominent U wave</div><div class=\"answer-line\">• T wave flattening</div><div class=\"answer-line\">Others (of equal value): PR prolongation, increased P wave amplitude and width, ST</div><div class=\"answer-line\">depression, <em>torsades de pointes</em>, atrial ectopics, ventricular ectopics, atrial tachyarrhythmias</div><div class=\"answer-line\">(fibrillation, flutter). NB: “arrhythmia” without qualification does not count.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Tall, tented T waves</div><div class=\"answer-line\">• Prolonged or widened QRS</div><div class=\"answer-line\">• Flattened, or loss of P waves</div><div class=\"answer-line\">• Others (of equal value):  Prolonged PR interval, sine wave pattern, bundle branch blocks,</div><div class=\"answer-line\">VF, asystole. NB: “arrhythmia” without qualification does not count.</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>List 3 treatment options for acute severe hyperkalaemia. For each, describe its</td><td>mechanism of action and time course (9 marks)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Briefly outline any concerns or issues related to using cation-exchange resins (calcium</div><div class=\"answer-line\">resonium) for the acute treatment of hyperkalaemia (2 marks)</div><div class=\"answer-line\">• Very slow onset/delay to effect (at least 4-10 hours…up to days)</div><div class=\"answer-line\">• Variable effect on lowering K (probably lowers it a bit after many hours)</div><div class=\"answer-line\">• Frequent constipation</div><div class=\"answer-line\">• Rare colonic necrosis  perforation</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 32 year old man is brought to your ED by ambulance with acute confusion, recent\ntiredness, 10 kg weight loss and heat intolerance. He appears to have bulging eyes. Vital signs are:\n\nHR\n146 bpm\n\nBP\n180/110 mmHg\n\nRR\n40 bpm\n\nSaO2 100 % RA\n\nGCS 13\n\nTemp 38.5 deg C","parts":[{"id":"a","label":"Part A","prompt":"State the most likely diagnosis and give 4 differential diagnoses for this presentation (5 marks)"},{"id":"b","label":"Part B","prompt":"Provide details of 3 specific pharmacological treatments for this condition and the role of each treatment (6 marks)"},{"id":"c","label":"Part C","prompt":"List 5 other management and disposition priorities (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">State the most likely diagnosis and give 4 differential diagnoses for this presentation</div><div class=\"answer-line\">(5 marks)</div><div class=\"answer-line\">• Thyroid storm</div><div class=\"answer-line\">• Meningoencephalitis</div><div class=\"answer-line\">• Sepsis – any source</div><div class=\"answer-line\">• Toxidromes (anticholinergic/sympathomimetic/serotonin syndrome/NMS)</div><div class=\"answer-line\">• Salicylate poisoning</div><div class=\"answer-line\">• Withdrawal of EtOH– DT’s</div><div class=\"answer-line\">• Withdrawal of BDZ/opiates</div><div class=\"answer-line\">• Heat stroke</div><div class=\"answer-line\">• Hypothalamic stroke</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Provide details of 3 specific pharmacological treatments for this condition and the role of</div><div class=\"answer-line\">each treatment (6 marks)</div><div class=\"answer-line\">• Beta blockers – eg Propranolol 1mg IV q 5mins up to 10mg, then 40 – 120mg q 6h</div><div class=\"answer-line\">regularly: block peripheral effects &amp; inhibits peripheral conversion T4 to T3, aim pulse</div><div class=\"answer-line\">&lt;100</div><div class=\"answer-line\">• PTU:  900 – 1200mg loading (PO/NG) then 200mg q4-6h: blocks de novo synthesis (or</div><div class=\"answer-line\">Carbimazole)</div><div class=\"answer-line\">• Iodine – Lugols iodine 8 -10 drops PO q 6h (or Na Iodine 1g IV bd): Prevents release</div><div class=\"answer-line\">stored hormones (NB must wait approx. 4 hours after PTU to ensure synthetic pathway</div><div class=\"answer-line\">blocked (or lithium carbonate if allergic to iodine)</div><div class=\"answer-line\">• Steroids – hydrocortisone 100mg q6h: tx steroid concomitant deficiency &amp; inhibits</div><div class=\"answer-line\">peripheral conversion T4 to active T3</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Cooling eg cooling blankets, cold fluids, antipyretics</div><div class=\"answer-line\">• Fluid resuscitation /ABCs</div><div class=\"answer-line\">• Seek and treat complications eg CV collapse</div><div class=\"answer-line\">• Seek and treat precipitants eg ECG for ACS, Abx for sepsis</div><div class=\"answer-line\">• Cultures/IV antibiotics if indicated</div><div class=\"answer-line\">• Urgent Endocrine review /admission</div><div class=\"answer-line\">• HDU review</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 32 year old man presents to your Emergency Department with a history of fever, lethargy\nand severe pain in his right groin and thigh. He has a history of intravenous drug use but is\n• therwise well and on no medications. On examination his right thigh is diffusely swollen,\nerythematous and has palpable crepitus.\nHis vital signs are:\n\nHR 120 bpm\n\nBP 85/40 mmHg\n\nT 40 deg C\n\nRR 20 bpm\n\nSaO2 99% RA","parts":[{"id":"a","label":"Part A","prompt":"What is your working diagnosis (3 marks)"},{"id":"b","label":"Part B","prompt":"Outline your key management steps (6 marks)"},{"id":"c","label":"Part C","prompt":"List 3 likely microorganisms to have caused this patient’s infection (3 marks)"},{"id":"d","label":"Part D","prompt":"The nurse reports this patient is extremely distressed with pain and is crying out for larger doses of analgesia and his methadone. List some principles of pain management in this patient with narcotic addiction (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Septic shock</div><div class=\"answer-line\">• Likely focus of infection – skin infection of the groin</div><div class=\"answer-line\">• Additional marks: necrotising fasciitis, infection likely due to direct injection to groin from</div><div class=\"answer-line\">IVDU</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Resuscitation:</div><div class=\"answer-line\">o Continuous cardiorespiratory monitoring</div><div class=\"answer-line\">o Large bore IV access and IVF resuscitation</div><div class=\"answer-line\">▪ Take off baseline bloods including blood cultures</div><div class=\"answer-line\">▪ 1000ml crystalloid stat (N/S)</div><div class=\"answer-line\">▪ Titrate to response – vitals/UO/lactate</div><div class=\"answer-line\">o Inotropes</div><div class=\"answer-line\">▪ Consider if no response , after 3L IVF resuscitation</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">▪ Noradrenaline (dose)</div><div class=\"answer-line\">• Early empirical IV antibiotics</div><div class=\"answer-line\">o Meropenem 1g q8hourly</div><div class=\"answer-line\">o Vancomycin 1g BD</div><div class=\"answer-line\">o Clindamycin 600mg q8hourly</div><div class=\"answer-line\">(Reference: eTG)</div><div class=\"answer-line\">• Analgesia</div><div class=\"answer-line\">• Early surgical referral for debridement (to remove devitalised tissue) a cornerstone of</div><div class=\"answer-line\">treatment</div><div class=\"answer-line\">• Consider Hyperbaric oxygen treatment</div><div class=\"answer-line\">• D&amp;A input</div><div class=\"answer-line\">• Imaging – CT leg/abdo to determine extent</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Staphylococcus aureus (esp IVDU)</div><div class=\"answer-line\">• Streptococci (esp Group A BH Strep – S.pyogenes)</div><div class=\"answer-line\">• Clostridium (C. perfringens)</div><div class=\"answer-line\">• Others ( E.coli, anaerobes eg bacteroides, vibrio if water involved)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">The nurse reports this patient is extremely distressed with pain and is crying out for larger</div><div class=\"answer-line\">doses of analgesia and his methadone. List some principles of pain management in this</div><div class=\"answer-line\">patient with narcotic addiction (4 marks)</div><div class=\"answer-line\">• Genuinely painful pathology, so do not withhold pain relief for fear of “drug seeking”, give</div><div class=\"answer-line\">adequate analgesia</div><div class=\"answer-line\">• Will have increased tolerance for narcotics, so will likely need larger and more frequent</div><div class=\"answer-line\">doses</div><div class=\"answer-line\">• Open discussion with patient</div><div class=\"answer-line\">• Analgesia ladder – don’t forget paracetamol, NSAIDs, mechanical principles (rest,</div><div class=\"answer-line\">elevation, keep sheets off area etc)</div><div class=\"answer-line\">• Get specialised input: D&amp;A, methadone provider, Anaesthetics/Pain team</div><div class=\"answer-line\">• At risk of narcotic withdrawal - discuss with nursing staff, commence withdrawal chart</div><div class=\"answer-line\">• Document plan carefully</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 4 year old previously well girl, presents with a sudden onset generalised tonic-clonic\nseizure lasting 40 minutes, terminated with one dose of midazolam. Immediately afterwards\nshe is GCS 3, and apnoeic.","parts":[{"id":"a","label":"Part A","prompt":"Briefly describe two methods for maintaining ventilation in this situation and the reason for your preferred method (4 marks)"},{"id":"b","label":"Part B","prompt":"List 5 possible causes of apnoea in this situation (5 marks)\nThe child improves to a GCS of 14 in 30 minutes. There are no focal neurological signs and no preceding illness or fever apart from the occasional headache. The child was born in Australia but spent 3 months in India returning 6 months ago. Her glucose and electrolytes are normal."},{"id":"c","label":"Part C","prompt":"List 5 possible causes for the seizure (5 marks)"},{"id":"d","label":"Part D","prompt":"Outline a pro and con of CT vs MRI of brain in this situation (4 marks) PRO CON MRI CT"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Briefly describe two methods for maintaining ventilation in this situation and the reason</div><div class=\"answer-line\">for your preferred method (4 marks)</div><div class=\"answer-line\">• Bag valve mask</div><div class=\"answer-line\">• +/- airway adjunct</div><div class=\"answer-line\">• LMA</div><div class=\"answer-line\">• Intubation and ventilation</div><div class=\"answer-line\">• BVM preferred method because least invasive and patient likely to recover once post</div><div class=\"answer-line\">ictal phase and midazolam has worn off and high CO2 washed out</div><div class=\"answer-line\">• LMA second line if BVM +AA fails</div><div class=\"answer-line\">• I and V if vomiting, potential aspiration</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Post ictal phase</div><div class=\"answer-line\">• Midazolam</div><div class=\"answer-line\">• Hypercapnoea (respiratory acidosis) from hypoventilation</div><div class=\"answer-line\">• Hypoglycaemia</div><div class=\"answer-line\">• Ongoing subclinical seizure</div><div class=\"answer-line\">• Coning due to space occupying lesions</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">• ICH/SDH/SAH (can count separately)</div><div class=\"answer-line\">• Tumour/abscess</div><div class=\"answer-line\">• Coning due to cerebral oedema</div><div class=\"answer-line\">• Electrolyte abnormalities</div><div class=\"answer-line\">• Meningitis (unlikely as the child was well)</div><div class=\"answer-line\">• Paralysis due electrolyte abnormalities (eg familial hypokalaemic paralysis)</div><div class=\"answer-line\">• Cord injury during handling or seizure</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• 1 mark per answer and extra mark if they mention neurocysticercosis or parasitic brain</div><div class=\"answer-line\">infestation</div><div class=\"answer-line\">• Otherwise many causes</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Post ictal phase</div><div class=\"answer-line\">• Midazolam</div><div class=\"answer-line\">• Hypercapnoea (respiratory acidosis) from hypoventilation</div><div class=\"answer-line\">• Hypoglycaemia</div><div class=\"answer-line\">• Ongoing subclinical seizure</div><div class=\"answer-line\">• Coning due to space occupying lesions</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">• ICH/SDH/SAH (can count separately)</div><div class=\"answer-line\">• Tumour/abscess</div><div class=\"answer-line\">• Coning due to cerebral oedema</div><div class=\"answer-line\">• Electrolyte abnormalities</div><div class=\"answer-line\">• Meningitis (unlikely as the child was well)</div><div class=\"answer-line\">• Paralysis due electrolyte abnormalities (eg familial hypokalaemic paralysis)</div><div class=\"answer-line\">• Cord injury during handling or seizure</div><div class=\"answer-line\">The child improves to a GCS of 14 in 30 minutes. There are no focal neurological signs and</div><div class=\"answer-line\">no preceding illness or fever apart from the occasional headache. The child was born in</div><div class=\"answer-line\">Australia but spent 3 months in India returning 6 months ago. Her glucose and electrolytes</div><div class=\"answer-line\">are normal.</div><div class=\"answer-line\">iii.</div><div class=\"answer-line\">• 1 mark per answer and extra mark if they mention neurocysticercosis or parasitic brain</div><div class=\"answer-line\">infestation</div><div class=\"answer-line\">• Otherwise many causes</div><div class=\"answer-line\">iv.</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">o PRO</div><div class=\"answer-line\">▪ Better pictures, better diagnostics, no radiation</div><div class=\"answer-line\">o CONS</div><div class=\"answer-line\">▪ Availability may make it too slow if there is a time critical problem going</div><div class=\"answer-line\">on. More likely to need a GA or sedation to keep still</div><div class=\"answer-line\">▪ Claustrophobia</div><div class=\"answer-line\">▪ Difficult to monitor pt in tunnel</div><div class=\"answer-line\">▪ Expensive</div><div class=\"answer-line\">o PRO</div><div class=\"answer-line\">▪ Quick and available in most departments.</div><div class=\"answer-line\">▪ Modern rapid scanners rarely need GA or sedation in children of this age</div><div class=\"answer-line\">▪ Good diagnostics esp for fractures and bleeds</div><div class=\"answer-line\">o CON</div><div class=\"answer-line\">▪ Not as good as MRI for soft tissue lesions/masses</div><div class=\"answer-line\">▪ Radiation cancer risk (?1:1000)</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"You are the consultant in a regional Emergency Department. A 5 year old girl re-presents\nhaving been discharged 7 hours ago. She was assessed during the previous presentation for\na head injury, sustained after a fall from a slide at preschool. No investigations were performed.","parts":[{"id":"a","label":"Part A","prompt":"List 6 indications for CT scan of brain for this child (6 marks)"},{"id":"b","label":"Part B","prompt":"Give 3 positive findings from the axial CT Image below (3 marks)\nA CT BRAIN IS SHOWN IN THE PROPS BOOKLET, PAGE 5"},{"id":"c","label":"Part C","prompt":"The child deteriorates to GCS 5. List your top 5 management priorities (5 marks)"},{"id":"d","label":"Part D","prompt":"Concerns about the management of the initial presentation are brought to your\nattention. Give 3 potential issues and action required (6 marks)"}],"propPages":["asset:imge8cb72701ee7f34785"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Definite indications: GCS &lt;15 or other signs of AMS; focal neurology; seizures: signs of</div><div class=\"answer-line\">basilar skull #: penetrating skull injury.</div><div class=\"answer-line\">• Consider if: persistent vomiting; ongoing persistent moderate/severe headache;</div><div class=\"answer-line\">delayed seizure; history of LOC; Post traumatic amnesia; clinical deterioration; parental</div><div class=\"answer-line\">concern;</div><div class=\"answer-line\">• CHALICE/PECARN/CATCH criteria</div><div class=\"answer-line\">• Decision rules exclude patients with bleeding disorder, pre-existing neuro</div><div class=\"answer-line\">disorder/tumour/shunt</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Left frontal <strong>extradural haematoma</strong>/left anterior cranial fossa, approximately 1.5 x 4cm</div><div class=\"answer-line\">• Left frontal lobe compressed slightly</div><div class=\"answer-line\">• Fluid in left frontal sinus</div><div class=\"answer-line\">• Air bubble</div><div class=\"answer-line\">• External soft tissue swelling</div><div class=\"answer-line\">• Debatable presence of midline shift</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Resuscitate: Move to RR/Team Leader. Delegate Roles. Resus Equipment/Monitoring</div><div class=\"answer-line\">RSI: ETT 5.5 (1 up and down).</div><div class=\"answer-line\">• RSI/Ventilation.  Maintain BP/avoid Hypotension and hypoxia. Appropriate drugs-</div><div class=\"answer-line\">ketamine. Ongoing sedation and paralysis.</div><div class=\"answer-line\">• CPP: Avoid Hypotension/hypoxia. Aim PaO2 100mmHg or more, low normal CO2. Head</div><div class=\"answer-line\">up. Avoid tight tapes. Mannitol/Hypertonic saline</div><div class=\"answer-line\">• Mobilise Surgeon (Burr holes/EVACUATION)/Retrieval team. Tertiary referral centre and</div><div class=\"answer-line\">Neurosurgery.</div><div class=\"answer-line\">• Inform parents/NOK/SW</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Concerns about the management of the initial presentation are brought to your</div><div class=\"answer-line\">attention. Give 3 potential issues and action required (6 marks)</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"You are the overnight registrar in your tertiary hospital ED. You receive an ambulance pre- arrival call at 2am for a 25 year old male, stabbed multiple times in the chest. ETA is 10 min.\n\nVital signs:\n\nHR 150 bpm\n\nBP 72/41 mmHg\n\nSaO2 90% on 15L\n\nRR 30 bpm\n\nGCS 12","parts":[{"id":"a","label":"Part A","prompt":"List 6 potential life threatening injuries in this patient (6 marks)"},{"id":"b","label":"Part B","prompt":"Briefly describe how you would prepare to receive this patient (5 marks)"},{"id":"c","label":"Part C","prompt":"What are the indications for ED thoracotomy in trauma (3 marks)"},{"id":"d","label":"Part D","prompt":"Provide an estimate of survival rates following ED thoracotomy for traumatic arrest (2 marks) In penetrating chest trauma In blunt trauma"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Cardiac- rupture, tamponade, damage to coronary arteries/ STEMI, contusion</div><div class=\"answer-line\">• Lung- haemothorax, pneumothorax, pulm laceration, hilar injury, bronchial/ trachea</div><div class=\"answer-line\">• Vessels- aorta, coronary, intercostals, pulmonary artery/ vein etc…</div><div class=\"answer-line\">• Abdominal organs/ diaphragm/ oesophagus</div><div class=\"answer-line\">• Others- Neck/Head</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">• Team- trauma team- allocate roles, ED reg, juniors, nurses, +/- anaesthetics, surgical reg,</div><div class=\"answer-line\">radiology- x-ray, brief them with plan, anticipate deterioration, PPE</div><div class=\"answer-line\">• Equipment- for intubation, thoracostomies/chest drain, thoracotomy, rapid transfusion,</div><div class=\"answer-line\">USS</div><div class=\"answer-line\">• Packed cells, TXA</div><div class=\"answer-line\">• Rest of Department- NUM, make sure other sick patients cared for, clear resus bay,</div><div class=\"answer-line\">• Rest of hospital-</div><div class=\"answer-line\">o ED physician on call</div><div class=\"answer-line\">o Cardiothoracics/ surgeons</div><div class=\"answer-line\">o Theatres</div><div class=\"answer-line\">o Anaesthetist</div><div class=\"answer-line\">o ICU</div><div class=\"answer-line\">o Blood bank- MTP</div><div class=\"answer-line\">o Security/ police</div><div class=\"answer-line\">o Social work/ media</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Widely accepted</div><div class=\"answer-line\">o Penetrating chest injury with cardiac arrest/ peri-arrest non-responsive to resus</div><div class=\"answer-line\">measures and signs of life within previous 10 (? 15) minutes</div><div class=\"answer-line\">• Controversial</div><div class=\"answer-line\">o Penetrating non-thoracic trauma (e.g. abdominal, peripheral) with traumatic arrest</div><div class=\"answer-line\">and witnessed signs of life/cardiac activity</div><div class=\"answer-line\">o Blunt trauma- with exsanguination from chest drain or pericardial tamponade seen</div><div class=\"answer-line\">on FAST or who lose signs of life/cardiac activity on arrival</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Provide an estimate of survival rates following ED thoracotomy for traumatic arrest (2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 68 year old female presents to your tertiary emergency department intoxicated, 2 hours\nafter deliberately ingesting 120 x 600mg tablets of slow release potassium. She has been\nvomiting and has a GCS of 14 (confused). An initial VBG is performed.\n\npH\n7.32 (7.35-7.45)\n\npCO2\n35 mmHg (35-38)\n\nLactate\n5 mmol/L (0.6-1.5) Creat 110 mcmol/L (45-90)\n\nBSL\n6.3 mmol/L (3.9-5.8)\n\nNa\n133 mmol/L (136-146)\n\nK\n6.1 mmol/L (3.9-5.2)\n\nHCO3\n18 mmol/L (21-28)\n\nBE\n-4 mmol/L (-1.5-3.0)","parts":[{"id":"a","label":"Part A","prompt":"Outline your risk assessment with regard to her ingestion (4 marks)"},{"id":"b","label":"Part B","prompt":"List and briefly describe 2 specific toxicological interventions that may be used to\nmanage her potassium ingestion (2 marks)"},{"id":"c","label":"Part C","prompt":"List an advantage and disadvantage for each of the methods listed above (4 marks)"},{"id":"d","label":"Part D","prompt":"List 4 other management priorities (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Agent -  Potassium potentially lethal OD</td></tr><tr><td>•</td><td>Dose   -  120 x 600mg - large ingestion</td></tr><tr><td>•</td><td>Time  -  &gt;1/24 post ingestion - absorption in progress ++</td></tr><tr><td>•</td><td>Patient factors - GCS 14 and vomiting ?toxicity ?co-ingestion/alcohol etc</td></tr><tr><td>•</td><td>Clinical -  Potassium already elevated on VBG</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">List and briefly describe 2 specific toxicological interventions that may be used to</div><div class=\"answer-line\">manage her potassium ingestion (2 marks)</div><div class=\"answer-line\">• GI decontamination – Whole bowel irrigation (Picoprep/PEGELS)</div><div class=\"answer-line\">• Increase clearance – Dialysis, via vascath in ICU</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>• GI decontamination</td><td>o decrease potassium load and often negates dialysis requirement in the setting of</td><td>normal renal function</td></tr><tr><td>o compliance -  intubate pt for WBI - resources/staff/gastric tube</td><td>placement/aspiration etc</td><td>• Dialysis</td></tr><tr><td>o definitive therapy</td><td>o invasive via vascath/central line, not in ED</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• IDC - urine output and strict fluid balance</div><div class=\"answer-line\">• Check BSL/temp/ECG/blds- para/ETOH</div><div class=\"answer-line\">• Xray ?confirm ingestion</div><div class=\"answer-line\">• Consult with poisons/tox</div><div class=\"answer-line\">• Specific to K</div><div class=\"answer-line\">o Elevated K+, ?ECG changes - fluids/renal excretion with e.g.  u/o &gt;1ml/kg/hr,</div><div class=\"answer-line\">insulin/dextrose/Ca2+</div><div class=\"answer-line\">o Serial K measure</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 35 year old female presents to your Emergency Department with an acute asthma attack.\nShe is highly distressed and only speaking single words despite continuous salbutamol nebs.","parts":[{"id":"a","label":"Part A","prompt":"List 4 markers of severe asthma (4 marks)"},{"id":"b","label":"Part B","prompt":"Complete the table below regarding the use of intravenous salbutamol and magnesium sulfate in asthma (8 marks) Indication and rationale Adverse Effects Intravenous salbutamol Magnesium Despite intensive therapy, and a period of non-invasive ventilation, the patient continues to deteriorate, appears exhausted and begins to tire rapidly. You decide intubation is required."},{"id":"c","label":"Part C","prompt":"Outline what your initial ventilator settings (4 marks)"},{"id":"d","label":"Part D","prompt":"List likely causes of climbing airway pressures in a ventilated asthmatic (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Inability to talk in full sentences</div><div class=\"answer-line\">• O2 saturations &lt; 90-92% PaO2 &lt; 60mmHg</div><div class=\"answer-line\">• PaCO2 &gt; 45</div><div class=\"answer-line\">• Use of accessory muscles, tracheal tugging</div><div class=\"answer-line\">• Pulsus paradoxus &gt; 15mmHg</div><div class=\"answer-line\">• Quiet chest</div><div class=\"answer-line\">• Unable to lie supine</div><div class=\"answer-line\">• Cyanosis, sweating</div><div class=\"answer-line\">• Confusion, decreased LOC</div><div class=\"answer-line\">• Bradycardia, hypotension</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">Complete the table below regarding the use of intravenous salbutamol and magnesium</td></tr><tr><td colspan=\"3\">sulfate in asthma (8 marks)</td></tr><tr><td>Indication and rationale</td><td>Adverse Effects</td><td></td></tr><tr><td>Intravenous</td><td>Critical/severe asthma where inhaled</td><td>(Compared to inhaled salbutamol)</td></tr><tr><td>salbutamol</td><td>B agonists cannot be effectively</td><td>Increase in autonomic adverse</td></tr><tr><td>delivered (e.g. ventilated patients)</td><td>effects</td><td></td></tr><tr><td colspan=\"3\">Increase in heart rate</td></tr><tr><td>IV salbutamol in addition to (or as</td><td>Hypokalaemia</td><td></td></tr><tr><td>replacement for) inhaled B agonists –</td><td>Lactic acidosis</td><td></td></tr><tr><td colspan=\"3\"><em>no evidence</em> to support</td></tr><tr><td colspan=\"3\">Efficacy in paeds unclear (too few</td></tr><tr><td colspan=\"3\">paediatric trials)</td></tr><tr><td colspan=\"3\">NSW Fellowship Course - SAQ trial paper 2017.1</td></tr><tr><td>Magnesium Main indication: severe asthma. No</td><td>Hypotension</td><td></td></tr><tr><td>benefit in mild/mod asthma</td><td>Depressed tendon reflexes</td><td></td></tr><tr><td colspan=\"3\">Muscle weakness</td></tr><tr><td>Reduces need for admission &amp;</td><td>Flushing</td><td></td></tr><tr><td>improves some lung function</td><td>Depressed cardiac function</td><td></td></tr><tr><td>parameters in patients with severe</td><td>CNS depression</td><td></td></tr><tr><td>asthma who have not responded</td><td>Respiratory depression</td><td></td></tr><tr><td colspan=\"3\">sufficiently to usual treatments</td></tr><tr><td colspan=\"3\">Paeds studies – small numbers so</td></tr><tr><td colspan=\"3\">evidence weak. May reduce need for</td></tr><tr><td colspan=\"3\">admission in moderate-severe asthma</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Needs a safe approach. Mention permissive hypercapnia &amp; lung protective strategy</div><div class=\"answer-line\">• Tidal volume  - low side - maximum of 8ml/kg (5-8)</div><div class=\"answer-line\">• RR – may need to be low – 6-8 breaths/min start at 10 bpm, but be prepared to titrate</div><div class=\"answer-line\">down</div><div class=\"answer-line\">• I:E ratio – &gt; 1:2, may need to be 1:5. May need to adjust inspiratory time to achieve</div><div class=\"answer-line\">• Fi02 titrated to keep SpO2 &gt; 92-94%</div><div class=\"answer-line\">• PEEP – controversial 0 – 5 mmHg (may have autopeep)</div><div class=\"answer-line\">• Limits – Peak insp &lt; 40, target plateau pressure &lt; 20 cmH2O</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Progression of disease – worsening bronchospasm</div><div class=\"answer-line\">• Pneumothorax</div><div class=\"answer-line\">• Air trapping/dynamic hyperinflation</div><div class=\"answer-line\">• Mucous plugging (bronchial, endotracheal tube)</div><div class=\"answer-line\">• Ventilator malfunction, inappropriate settings</div><div class=\"answer-line\">• Patient-ventilator dysynchrony</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"This is the ear of a 40-year-old male who has developmental delay with autism.\nA CLINICAL IMAGE IS SHOWN IN THE PROPS BOOKLET, PAGE 6","parts":[{"id":"a","label":"Part A","prompt":"Describe and interpret the image (2 marks)"},{"id":"b","label":"Part B","prompt":"List two possible predisposing conditions (2 marks)"},{"id":"c","label":"Part C","prompt":"List two complications (2 marks)"},{"id":"d","label":"Part D","prompt":"Name the three bacteria typically involved (3 marks)"},{"id":"e","label":"Part E","prompt":"Name one suitable antibiotic choice for this condition (1 mark) This developmentally delayed man is distressed about being in hospital. He is currently pacing and will not come into the assessment room."},{"id":"f","label":"Part F","prompt":"List 3 non-pharmacological strategies or techniques you can use to manage his agitation\n(3 marks)"}],"propPages":["asset:img45fdc77f4f8897f560"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Extensive redness and swelling of the pinna/external ear. Some extension onto neck</div><div class=\"answer-line\">• Perichondritis or cellulitis of the external ear</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Otitis externa</div><div class=\"answer-line\">• Tick or insect bite</div><div class=\"answer-line\">• High ear piercing, other local trauma</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Cartilage necrosis/cauliflower ear</div><div class=\"answer-line\">• Local abscess</div><div class=\"answer-line\">• Deep extension eg cerebral abscess, mastoiditis</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Staph aureus</div><div class=\"answer-line\">• Strep pyogenes</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">• Must include Pseudomonas cover or no marks</div><div class=\"answer-line\">• Quinolone eg ciprofloxacin PO or IV</div><div class=\"answer-line\">• Gentamicin IV and a penicillin IV</div><div class=\"answer-line\">• Anti-pseudomonas cephalosporin eg ceftazidime IV</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">List 3 non-pharmacological strategies or techniques you can use to manage his agitation</div><div class=\"answer-line\">(3 marks)</div><div class=\"answer-line\">• Familiar people and objects. Involve his carer, favourite soft toy</div><div class=\"answer-line\">• Distraction. eg screentime, music via headphones</div><div class=\"answer-line\">• Low stimulus environment, minimise distractions, noise and lights</div><div class=\"answer-line\">• Explain procedure in simple language and diagrams</div><div class=\"answer-line\">• Minimise staff involved to build relationships</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 74 year old man presents after a fall the night before. He is now complaining of reduced mobility. Past medical history includes atrial fibrillation and hypertension. His medications are dabigatran, metoprolol and aspirin. GCS is 15.","parts":[{"id":"a","label":"Part A","prompt":"Outline the findings on the CT image (4 marks) A CT BRAIN IS SHOWN IN THE PROPS BOOKLET, PAGE 7"},{"id":"b","label":"Part B","prompt":"List 4 possible treatments you would consider using and your rationale for each (8marks)"},{"id":"c","label":"Part C","prompt":"List 2 important additional features on assessment that are required to assist your\ntreatment decision (2 marks)"},{"id":"d","label":"Part D","prompt":"List one other option for the management of NOAC associated bleeding (1 mark)"}],"propPages":["asset:img3913e97d30f0f05747"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Acute on chronic left subdural haemorrhage overlying the left cerebral convexity,</div><div class=\"answer-line\">tentorium and parafalcine location. Maximal thickness of this SDH is 23mm</div><div class=\"answer-line\">• Mass effect with 5mm shift of midline structures to the right and early hydrocephalus</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>NSW Fellowship Course - SAQ trial paper 2017.1</td><td>• Blood products if required – Packed RBC, Platelets</td></tr><tr><td>o PRBC for severe anaemia/ongoing blood loss</td><td>o Platelet transfusion for thrombocytopaenia and/or severe platelet dysfunction</td></tr><tr><td>• Tranexamic Acid (antifibrinolytic agent)</td><td>o Low cost and risk (of thrombosis, adverse reaction), therefore should be</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List 2 important additional features on assessment that are required to assist your</div><div class=\"answer-line\">treatment decision (2 marks)</div><div class=\"answer-line\">• Time of ingestion of last DOAC dose</div><div class=\"answer-line\">• Assessment of renal and hepatic function</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Haemodialysis – Dabigatran is 80-85% renally excreted. (Not useful in Direct Factor Xa</div><div class=\"answer-line\">oral Inhibitors eg rivaroxaban, apixaban as only 25-35% renal excretion; they are mostly</div><div class=\"answer-line\">protein bound)</div><div class=\"answer-line\">• Charcoal if ingested &lt;2hrs prior – reduces absorption</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 12 year old girl was brought to ED via ambulance following a syncopal episode.","parts":[{"id":"a","label":"Part A","prompt":"What is the definition of syncope (3 marks)"},{"id":"b","label":"Part B","prompt":"What is the most common cause of syncope in children (1 mark)"},{"id":"c","label":"Part C","prompt":"Name a form of syncope unique to the preschool population (1 mark)"},{"id":"d","label":"Part D","prompt":"List 5 red flags in this girl’s history that would prompt further investigation (5 marks)"},{"id":"e","label":"Part E","prompt":"List 5 conditions you would look for in this girl’s ECG (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Abrupt loss of conscious ness and postural tone resulting from transient global cerebral</div><div class=\"answer-line\">hypoperfusion followed by spontaneous complete recovery</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Neuro-cardiogenic syncope OR vasovagal syncope</div><div class=\"answer-line\">iii.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Breath holding spells</div><div class=\"answer-line\">iv.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Syncope during exercise/supine</div><div class=\"answer-line\">• Chest pain prior</div><div class=\"answer-line\">• Palpitations prior</div><div class=\"answer-line\">• Known structural heart disease</div><div class=\"answer-line\">• Family Hx dysrhythmias, sudden death</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">v.</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">• Pre-excitation/WPW</div><div class=\"answer-line\">• Long QT</div><div class=\"answer-line\">• Short QT</div><div class=\"answer-line\">• Brugada</div><div class=\"answer-line\">• HOCM</div><div class=\"answer-line\">• AV nodal block</div><div class=\"answer-line\">• ARVD</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 26 year old primigravida presents at 36 weeks gestation with jaundice, blurred vision and hypertension (180/100 mmHg). The antenatal period was otherwise unremarkable. The following are her blood results:\n\nHb\n80g/L (115 - 160) 52 x 109/L\n\nPlatelets\n(140 - 400)\n\nINR\n1.8 (0.9 - 1.3)\n\nAPTT\n55 seconds (25 - 38) LDH 654 U/L (110 - 250) Fibrinogen 1.0 G/L (1.5 - 4.0)\nTotal bilirubin 51 micromol/L\n(< 20)","parts":[{"id":"a","label":"Part A","prompt":"List the four most likely diagnoses for this clinical presentation (4 marks)"},{"id":"b","label":"Part B","prompt":"Outline 4 priorities in your management (4 marks)"},{"id":"c","label":"Part C","prompt":"She starts to have a generalised seizure. List 2 medications with doses that you might administer (2 marks)"},{"id":"d","label":"Part D","prompt":"List the findings on a cardiotocograph (CTG) trace that would indicate foetal distress (4 marks) CTG Feature Non-reassuring or Abnormal values Baseline rate Decelerations"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• HUS – TTP</div><div class=\"answer-line\">• Biliary disease</div><div class=\"answer-line\">• Acute fatty liver of pregnancy</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">• IV access and resus</div><div class=\"answer-line\">• Contact O&amp;G, anaesthetics, paediatrics – may require immediate delivery of baby</div><div class=\"answer-line\">• Treat hypertension – IV hydralazine 5mg every 5 - 10 minutes, aim SBP &lt;150, DBP &lt;105</div><div class=\"answer-line\">• Prevention of seizures – MgSO4 4g IV</div><div class=\"answer-line\">• Consider correction coagulopathy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">She starts to have a generalised seizure. List 2 medications with doses that you might</div><div class=\"answer-line\">administer (2 marks)</div><div class=\"answer-line\">• 4g Magnesium followed by 1g/hour magnesium infusion, Mg can be repeated every 5</div><div class=\"answer-line\">minutes 2g</div><div class=\"answer-line\">• BZD – midazolam 5mg IV, not first line</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">List the findings on a cardiotocograph (CTG) trace that would indicate foetal distress (4</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 72 year old male presents via ambulance short of breath. He is sweaty and looks unwell\nbut is conscious. He has a history of IHD and has an AICD in situ.\n\nVital signs\nP 150 bpm\n\nBP 75/- mmHg\n\nRR 30 bpm\n\nSaO2 96% 15LNRB","parts":[{"id":"a","label":"Part A","prompt":"What rhythm is shown (1 mark)\nA 12 LEAD ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 8\nYou decide to perform DC cardioversion to treat the rhythm noted above. A VBG done after a cannula is placed shows the following.\n\npH\n7.35 (7.35-7.45)\n\npCO2\n57 mmHg (32-45)\n\nLactate\n3.3 mmol/L (0.5-1.6)\n\nK\n6.1 mmol/L (3.5-5.2)\n\nCr\n160 mcmol/L (60-110)"},{"id":"b","label":"Part B","prompt":"What other treatment is required while cardioversion is being arranged (2 marks)"},{"id":"c","label":"Part C","prompt":"Outline 2 pharmacologic agents you could use for sedation in this patient with initial\ndoses and indicating an advantages and disadvantage for each (8 marks) Drug Dose Advantage Disadvantage"},{"id":"d","label":"Part D","prompt":"Describe what settings you would set on the defibrillator and the positioning of the pads\n• n the patient (2 marks)"},{"id":"e","label":"Part E","prompt":"After cardioversion with sedation his rhythm is as follows. Describe the rhythm (1 mark) A RHYTHM STRIP IS SHOWN IN THE PROPS BOOKLET, PAGE 8"},{"id":"f","label":"Part F","prompt":"Despite the ECG change the patient remains hypotensive, P 100bpm, SBP 80mmHg. Give 2 differential diagnoses for this (2 marks)"}],"propPages":["asset:img2a9dc5ad13ae18477e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• VT</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Urgent treatment of hyperkalaemia. <strong>CaCl for hyperkalaemia</strong> and malignant rhythm</div><div class=\"answer-line\">10mml 10% repeated if no change to ECG. Consideration of insulin/dextrose/and IV</div><div class=\"answer-line\">NaHCO3</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>Outline 2 pharmacologic agents you could use for sedation in this patient with initial</td><td>doses and indicating advantages/disadvantages for each (8 marks)</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Describe what settings you would set on the defibrillator and the positioning of the pads</div><div class=\"answer-line\">on the patient (2 marks)</div><div class=\"answer-line\">• Synchronised 200 J, pads standard or AP with 10cm clearance of AICD box</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">• AF with VEB</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Despite the ECG change the patient remains hypotensive, P 100bpm, SBP 80mmHg. Give</div><div class=\"answer-line\">2 differential diagnoses for this (2 marks)</div><div class=\"answer-line\">• Drug effect of sedation/stunned myocardium/NSTEMI/sepsis</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 12 month old Asian boy is brought to the ED by his parents. Over the last 48 hours his\nmother noticed him becoming increasingly pale and lethargic and noted his urine was dark. He was seen by his GP 4 days ago with fever, vomiting and cloudy urine which settled with a course of trimethoprim. He is haemodynamically stable and apyrexial.","parts":[{"id":"a","label":"Part A","prompt":"List 4 possible causes of this presentation (4 marks)\nHe has the following blood results: 11.8 x109/L\n\nWCC\n(3.6-11) 7.3 x 109/L Neutrophils (1.8-7.5)\n\nHb\n60g/L (115-165) Hct 0.29L/L (0.37-0.44) 500 x 109/L Plt (140-400) 3.5 x 1012/L RCC (3.8-5.8) MCV 90 fL (80-96) MCHC 320g/L (285-300) 240x109/L Reticulocyte count (30-140) DAT / Coombs test - negative EUC - normal"},{"id":"b","label":"Part B","prompt":"Describe and interpret the above results (2 marks)"},{"id":"c","label":"Part C","prompt":"List 4 other investigations to help confirm the likely diagnosis and provide your\nreasoning (8 marks)"},{"id":"d","label":"Part D","prompt":"You suspect he has G6PD. List 4 causes of this condition (4 marks)"},{"id":"e","label":"Part E","prompt":"What would be your treatment for this patient (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">• Haemolytic uraemic syndrome</td></tr><tr><td colspan=\"3\">• Haemolytic anaemia – only one mark for haemoglobinopathies</td></tr><tr><td colspan=\"3\">• Infection with dehydration</td></tr><tr><td colspan=\"3\">• Hepatitis / Cholecystitis / porphyria / dengue / malaria / intussusception</td></tr><tr><td colspan=\"3\">He has the following blood results:</td></tr><tr><td>WCC</td><td>11.8 x109/L</td><td>(3.6-11)</td></tr><tr><td>Neutrophils</td><td>7.3 x 109/L</td><td>(1.8-7.5)</td></tr><tr><td>Hb</td><td>60g/L</td><td>(115-165)</td></tr><tr><td>Hct</td><td>0.29L/L</td><td>(0.37-0.44)</td></tr><tr><td>Plt</td><td>500 x 109/L</td><td>(140-400)</td></tr><tr><td>RCC</td><td>3.5 x 1012/L</td><td>(3.8-5.8)</td></tr><tr><td>MCV</td><td>90 fL</td><td>(80-96)</td></tr><tr><td>MCHC</td><td>320g/L</td><td>(285-300)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Normocytic, normochromic severe anaemia, associated reticulocytosis. Coombs</div><div class=\"answer-line\">negative (non immune mediated)</div><div class=\"answer-line\">• Suggestive haemolytic anaemia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List 4 other investigations to help confirm the likely diagnosis and provide your</div><div class=\"answer-line\">reasoning (8 marks)</div><div class=\"answer-line\">• Bilirubin – increased indirect</div><div class=\"answer-line\">• Haptoglobins- decreased</div><div class=\"answer-line\">• LDH – elevated</div><div class=\"answer-line\">• Coags</div><div class=\"answer-line\">• U/A and micro – casts = renal, haematuria, urinary haemosiderin (severe haemolysis)</div><div class=\"answer-line\">• Blood film – polychromasia – increased RBC production, bite cells – splenic removal hb,</div><div class=\"answer-line\">Heinz bodies, rule out malaria</div><div class=\"answer-line\">• G6PD level – should be taken during well stages so no mark for this</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Drugs – antimalarials, sulphonamides, cipro, aspirin (one mark only)</div><div class=\"answer-line\">• Infections – multiple – (one mark only)</div><div class=\"answer-line\">• Napthalene blue (moth balls)</div><div class=\"answer-line\">• Fava beans</div><div class=\"answer-line\">• Ketoacidosis</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">• Cease trimethoprim</div><div class=\"answer-line\">• Admission paediatrics</div><div class=\"answer-line\">• Supportive – IV fluids (reduce ketoacidosis / oxidative stress)</div><div class=\"answer-line\">• Oral folate</div><div class=\"answer-line\">• Does not require blood transfusion – no mark for suggesting this</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 41 year old man presents with a brief syncopal episode. He has no significant past medical history, medications or allergies. On examination he is alert and cardio-respiratory exam is normal.\n\nVital signs\n\nHR\n96 bpm\n\nBP\n135/80 mmHg\n\nRR\n12 bpm\n\nSaO2 RA\n96%\n\nTemp\n36.5 deg C\n\nBSL\n5 mmol/L","parts":[{"id":"a","label":"Part A","prompt":"Describe the most significant finding on this ECG and state the most concerning diagnosis given the clinical setting (2 marks)\nA 12 LEAD ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 9"},{"id":"b","label":"Part B","prompt":"List 4 differential diagnoses for this ECG pattern (4 marks)"},{"id":"c","label":"Part C","prompt":"List 4 relevant questions you would ask the patient (4 marks)"},{"id":"d","label":"Part D","prompt":"Outline the important components of his disposition, follow-up and ongoing management (4 marks)"}],"propPages":["asset:img6d7dbb416fca40b8be"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Describe the most significant finding on this ECG and state the most concerning</div><div class=\"answer-line\">diagnosis given the clinical setting (2 marks)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">• Atypical RBBB</div><div class=\"answer-line\">• Myocardial ischaemia/infarction</div><div class=\"answer-line\">• Benign Early Repolarisation</div><div class=\"answer-line\">• PE</div><div class=\"answer-line\">• Myo/pericarditis</div><div class=\"answer-line\">• Athletes</div><div class=\"answer-line\">• Pectus excavatum</div><div class=\"answer-line\">• RV outflow obstruction or other RV abnormality</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Family history of sudden cardiac death  &lt; 45 years of age</div><div class=\"answer-line\">• Triggers such as any fever?  Drugs? eg Na ch blocker, CCB, BB, nitrates, alpha agonist,</div><div class=\"answer-line\">cocaine, alcohol</div><div class=\"answer-line\">• Exertion related</div><div class=\"answer-line\">• Nocturnal agonal respirations</div><div class=\"answer-line\">• Others</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Outline the important components of his disposition, follow-up and ongoing</div><div class=\"answer-line\">management (4 marks)</div><div class=\"answer-line\">• Admit for monitoring – explain concern for serious dysrhythmia</div><div class=\"answer-line\">• Cardiology referral and regular follow up will be required; consideration for ICD</div><div class=\"answer-line\">• Family screening is strongly recommended in first-degree relatives (autosomal dominant</div><div class=\"answer-line\">inherited disease); genetic counselling/testing if available (but low diagnostic yield)</div><div class=\"answer-line\">• Avoid drugs/triggers eg as mentioned above</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 30 year old man presents to your ED with a 24 hour history of increasing weakness.\nAn ABG and electrolytes are performed.\n\nABG\n\nFiO2 21%\n\npH\n7.26 mmHg (7.35-7.45)\n\npCO2 29 mmHg\n(35-48)\n\npO2\n101 mmHg (83-108)\n\nHCO3 13 mmol/L\n(21-28)\n\nBE\n-13 mmol/L (-1.5-3.0) ELECTROLYTES\n\nNa\n137 mmol/L (136-146)\n\nK\n1.8 mmol/L (3.9-5.2)\n\nCL\n116 mmol/L (95-110)\n\nUrea 7.8 mmol/L\n(3.1-8.1)\nCreat 86 mmol/L\n(60-110) Glc 4.0 mmol/L (3.9-5.8) CK 1975 U/L (29-168)\nTrop T 20 ng/L\n(<30)","parts":[{"id":"a","label":"Part A","prompt":"Describe and interpret his blood results (8 marks)"},{"id":"b","label":"Part B","prompt":"List your 3 immediate management priorities (3 marks)"},{"id":"c","label":"Part C","prompt":"An internal jugular central venous catheter is placed to facilitate potassium\nreplacement. List 4 early and 4 late complications of internal jugular central venous\ncatheter placement (8 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• AG = Na – (Cl + HCO3) = 137 – (116 + 13) = 8</div><div class=\"answer-line\">• Causes of NAGMA include pancreato/uretero-enterostomies, small bowel</div><div class=\"answer-line\">fistulae, excess chloride, diarrhoea, carbonic anhydrase inhibitors, RTA,</div><div class=\"answer-line\">Addison’s.</div><div class=\"answer-line\">• <strong>Appropriate respiratory compensation </strong></div><div class=\"answer-line\">• Expected CO2 = 1.5 x bicarb + 8 = 28</div><div class=\"answer-line\">• <strong>Severe hypokalaemia</strong> likely cause of weakness - ? secondary to chronic diarrhoea, may</div><div class=\"answer-line\">be hereditary</div><div class=\"answer-line\">• <strong>Mild elevation in CK</strong> – likely just dehydration, could be due to: infection, hypokalaemia,</div><div class=\"answer-line\">metabolic (thyroid storm, phaechromocytoma). Not severe rhabdomyolysis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Move to monitored bed. Need for ECG</div><div class=\"answer-line\">• Needs potassium replacement in monitored environment, likely to need central line for</div><div class=\"answer-line\">IV potassium replacement. Need to contact HDU</div><div class=\"answer-line\">• Need for IVF as likely element of pre-renal failure in view of mild CK rise</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">An internal jugular central venous catheter is placed to facilitate potassium</td></tr><tr><td colspan=\"2\">replacement. List 4 early and 4 late complications of internal jugular central venous</td></tr><tr><td colspan=\"2\">catheter placement (8 marks)</td></tr><tr><td colspan=\"2\">Immediate/Early</td></tr><tr><td>•</td><td>pneumothorax</td></tr><tr><td>•</td><td>failure to locate vein</td></tr><tr><td>•</td><td>accidental arterial puncture</td></tr><tr><td>•</td><td>haemothorax</td></tr><tr><td>•</td><td>haematoma</td></tr><tr><td>•</td><td>arrhythmia</td></tr><tr><td>•</td><td>thoracic duct injury</td></tr><tr><td>•</td><td>guide wire embolus</td></tr><tr><td>•</td><td>air embolus</td></tr><tr><td>•</td><td>haemopericardium and tamponade</td></tr><tr><td>•</td><td>pneumothorax</td></tr><tr><td>•</td><td>catheter blockage</td></tr><tr><td>•</td><td>chylothorax</td></tr><tr><td>•</td><td>catheter knots</td></tr><tr><td colspan=\"2\">Late</td></tr><tr><td>•</td><td>infection (no difference in the rate of catheter-related bloodstream infections</td></tr><tr><td colspan=\"2\">between the IJ, SC and Femoral sites -&gt; 2.5 infections/ 1000 catheter days)</td></tr><tr><td>•</td><td>catheter fracture</td></tr><tr><td>•</td><td>vascular erosion</td></tr><tr><td>•</td><td>vessel stenosis</td></tr><tr><td>•</td><td>thrombosis</td></tr><tr><td>•</td><td>osteomyelitis of clavicle</td></tr><tr><td colspan=\"2\">NSW Fellowship Course - SAQ trial paper 2017.1</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"This 23 year old man sustained isolated dental trauma in a fall.\nA CLINICAL IMAGE IS SHOWN IN THE PROPS BOOKLET, PAGE 10","parts":[{"id":"a","label":"Part A","prompt":"Briefly describe two methods of anaesthetising the affected teeth (4 marks)"},{"id":"b","label":"Part B","prompt":"Describe the injury to the upper left lateral incisor (tooth 22) (2 marks)"},{"id":"c","label":"Part C","prompt":"Assuming a 12 hour delay to see a dentist, outline the Emergency Department\ntreatment of this tooth injury (4 marks)"},{"id":"d","label":"Part D","prompt":"List 3 possible adverse dental sequelae of this tooth injury (3 marks)"}],"propPages":["asset:imgcd6c8e24031c05695d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Local infiltration = supraperiosteal infiltration.  2mL of lignocaine injected approx 2mm</div><div class=\"answer-line\">deep into the deepest part of sulcus formed by reflection of the buccal &amp; gingival</div><div class=\"answer-line\">mucosa directly opposite affected tooth.</div><div class=\"answer-line\">• Infra-orbital nerve block. Palpate infraorbital notch, slide finger just below orbital rim.</div><div class=\"answer-line\">Infiltrate 2mL of lignocaine at that site. Could also use the intra-oral approach through</div><div class=\"answer-line\">mucosal sulcus up to foramen</div><div class=\"answer-line\">• Anterior superior alveolar nerve block. Use intra-oral approach like for infra-orbital n</div><div class=\"answer-line\">block</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Extrusive luxation (partially extruded from socket), displaced posteriorly – also has an</div><div class=\"answer-line\">uncomplicated crown fracture with dentine visible (no pulp) [Ellis Class II]</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Assuming a 12 hour delay to see a dentist, outline the Emergency Department</div><div class=\"answer-line\">treatment of this tooth injury (4 marks)</div><div class=\"answer-line\">• Ideally need OPG to assess fracture of alveolar bone</div><div class=\"answer-line\">• Local anaesthetic (see above), analgesia</div><div class=\"answer-line\">• Reinsert tooth into normal position (mould alveolar bone if needed, check occlusion)</div><div class=\"answer-line\">• Splint to adjacent teeth with Glass Ionomer Cement (GIC). If no GIC available need</div><div class=\"answer-line\">alternate splint – e.g. “blue tac” and a mouth guard</div><div class=\"answer-line\">• Cover exposed fracture surface (dentine) with GIC</div><div class=\"answer-line\">• If no GIC available needs relatively urgent (&lt; 24h) f/u with dentist</div><div class=\"answer-line\">• Will need splinting for 2-4 weeks</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Pulpitis/Dental abscess</div><div class=\"answer-line\">• Pulp necrosis</div><div class=\"answer-line\">• Ankylosis</div><div class=\"answer-line\">• Root resorption</div><div class=\"answer-line\">• Need for root canal therapy</div><div class=\"answer-line\">• Tooth colour change</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 7 year old boy presents to your ED with an injury to his right elbow after a fall. The elbow is obviously deformed and swollen.","parts":[{"id":"a","label":"Part A","prompt":"What are the immediate issues that need to be addressed (3 marks)"},{"id":"b","label":"Part B","prompt":"Describe the X-ray findings (3 marks) AN XRAY IS SHOWN IN THE PROPS BOOKLET, PAGE 11"},{"id":"c","label":"Part C","prompt":"List 4 potential implications of this injury (4 marks)"},{"id":"d","label":"Part D","prompt":"Describe the course of the ulnar nerve at the elbow (2 marks) and list the forearm and hand muscles potentially affected by ulnar nerve injury (3 marks)"}],"propPages":["asset:img4664d212ceee4ad86b","asset:imgf510aa8920035f607d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Analgesia</div><div class=\"answer-line\">• Is there neuro/vascular compromise? Time-frame to reduction?</div><div class=\"answer-line\">• Splint / sling</div><div class=\"answer-line\">• History, consider mechanism, consider NAI??</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Obvious dislocation of the elbow posteriorly and laterally</div><div class=\"answer-line\">• On lateral view there is a small bony fragment above the epiphysis.</div><div class=\"answer-line\">• Applying CRITOE you can deduce that there is a displaced fracture of the medial</div><div class=\"answer-line\">epicondyle (which should be ossified at 5 years). It is not the olecranon. AP view shows</div><div class=\"answer-line\">medial epicondyle ‘missing’</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Neurovascular compromise. If present will need immediate reduction</div><div class=\"answer-line\">• Difficulty in relocation in view of displaced medial epicondyle. Will need specialist input</div><div class=\"answer-line\">and likely OT regardless of ED management. Need for expert assistance – OT reduction</div><div class=\"answer-line\">preferable</div><div class=\"answer-line\">• Long term issues – malunion, non-union, poor function, neurovascular impairment</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Arises from brachial plexus, descends down medial side of upper arm, passes posterior</div><div class=\"answer-line\">to medial epicondyle to enter forearm, pierces the two heads of FCU then descends</div><div class=\"answer-line\">alongside the ulna</div><div class=\"answer-line\">• FCU and medial half of FDP, interossei, medial two lumbricals. Wrist flexion can occur</div><div class=\"answer-line\">but accompanied by abduction, impaired adduction at wrist, abnormal finger</div><div class=\"answer-line\">add/abduction</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 70 year old man presents with a painful facial rash that started 5 days ago. There have\nbeen no new skin lesions for 24 hrs. Vital signs are normal but he is distressed with pain. A CLINICAL IMAGE IS SHOWN IN THE PROPS BOOKLET, PAGE 12","parts":[{"id":"a","label":"Part A","prompt":"Describe the appearances seen in this photograph (3 marks)"},{"id":"b","label":"Part B","prompt":"List the most likely diagnosis (1 mark)"},{"id":"c","label":"Part C","prompt":"List 4 complications of this condition. For each of these, list one examination finding that would support the existence of the complication (8 marks)"},{"id":"d","label":"Part D","prompt":"Outline your management for this patient (5 marks)"}],"propPages":["asset:imge7bb65df35524e8320"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Erythema in right forehead CNV1/unilat forehead distribution/dermatomal</div><div class=\"answer-line\">• Crusting and scab to the same distribution</div><div class=\"answer-line\">• Right eye closed ? ptosis</div><div class=\"answer-line\">• Fluorescein staining to right eyelids</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Herpes Zoster</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>List 4 complications of this condition. For each of these, list one examination finding that</td><td>would support the existence of the complication (8 marks)</td></tr><tr><td>NSW Fellowship Course - SAQ trial paper 2017.1</td><td>• Ocular ulceration/keratitis (zoster ophthalmicus)</td></tr><tr><td>o Slit lamp evidence of ulceration/VA</td><td>• Transverse Myelitis</td></tr><tr><td>o Neurological findings in limbs</td><td>• Bells Palsy</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Ocular protection – eye taping (not padding as pressure effects)</div><div class=\"answer-line\">• Ocular lubrication – chlorsig drops or ointment 4-5/day/ or lubricant drops</div><div class=\"answer-line\">• Analgesia – Panadol/Nurofen/Opiates (with doses), consider early amitryptiline if</div><div class=\"answer-line\">ongoing pain (?PHN) – amitryptiline 25mg nocte</div><div class=\"answer-line\">• Antivirals - Too late for aciclovor/famciclovir for skin as &gt;72 hrs and no new lesions –</div><div class=\"answer-line\">however if eye involved can use</div><div class=\"answer-line\">o Aciclovir 800 mg orally 5 times a day for one week, or</div><div class=\"answer-line\">o Famciclovir 250 mg orally 8 hourly for one week, or</div><div class=\"answer-line\">o Valaciclovir 1 g orally 8 hourly for one week</div><div class=\"answer-line\">o May supplement with topical acyclovir</div><div class=\"answer-line\">o IV aciclovir if sight threatened</div><div class=\"answer-line\">• Ophthalmology involvement</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 53 year old female had a syncopal episode and collapsed onto an electric heater. She\nsustained a facial burn. She is now haemodynamically stable and GCS 15. You are in a rural ED. A CLINICAL IMAGE IS SHOWN IN THE PROPS BOOKLET, PAGE 13","parts":[{"id":"a","label":"Part A","prompt":"List 4 issues to consider in your assessment of this patient (4 marks)"},{"id":"b","label":"Part B","prompt":"How would you describe this burn to the burns registrar on call at the tertiary hospital (2 marks)"},{"id":"c","label":"Part C","prompt":"Outline 4 issues in the management of this burn (4 marks)"},{"id":"d","label":"Part D","prompt":"List 2 possible adverse sequelae from this burn (2 marks)"}],"propPages":["asset:imgc1bc14fabe8a248f62"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Cardiac monitoring/ECG/other investigations for <strong>cause of syncope</strong></div><div class=\"answer-line\">• Assess for<strong> airway involvement</strong></div><div class=\"answer-line\">• Assess for signs of head/neck/ other injury – e.g. fluctuant/altered GCS, lacerations,</div><div class=\"answer-line\">haematoma, haemotympanum</div><div class=\"answer-line\">• Tetanus status?</div><div class=\"answer-line\">• Other</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">How would you describe this burn to the burns registrar on call at the tertiary hospital (2</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">• Burn involves approx. 2% TBSA</div><div class=\"answer-line\">• Central area of full thickness burn (approx. 1% TBSA) with white/leathery appearance of</div><div class=\"answer-line\">skin and no capillary refill</div><div class=\"answer-line\">• Surrounded by partial thickness burn with evidence of deroofed blisters</div><div class=\"answer-line\">• Area extends from the patients left ear (involving the inferior 2 thirds of their helix,</div><div class=\"answer-line\">antihelix and the tragus), the majority of the patients left maxillary, mandibular and</div><div class=\"answer-line\">zygomatic areas, to the patient’s chin.</div><div class=\"answer-line\">• Left eye, lips and airway appear to be spared</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Administer first aid if not already received – cool running water for 20mins</div><div class=\"answer-line\">• Tetanus booster</div><div class=\"answer-line\">• Appropriate analgesia</div><div class=\"answer-line\">• Apply appropriate dressing (ie Silver-based eg acticoat) or bactigras</div><div class=\"answer-line\">• Refer to a burns centre as this is a full thickness facial burn that will require a skin graft –</div><div class=\"answer-line\">needs tertiary management</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Infection (left ear particularly at risk given it is a cartilaginous structure)</div><div class=\"answer-line\">• Involvement of facial nerve, resulting in facial droop on the left side</div><div class=\"answer-line\">• Permanent scarring</div><div class=\"answer-line\">• Others</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 6 year old girl is brought to the emergency department by her mother. She has had a cold for 1 week, and for the last 24 hours her right eyelid has become very red and swollen. She is unable to open her eye. Her temperature is 38.4 degrees Celsius.","parts":[{"id":"a","label":"Part A","prompt":"In the table below list 4 examination findings for each condition that may differentiate\npre-septal from post-septal cellulitis (8 marks) Pre-septal Post-septal"},{"id":"b","label":"Part B","prompt":"List 2 bacteria that can cause this presentation (2 marks)"},{"id":"c","label":"Part C","prompt":"List appropriate antibiotic therapy (include route and dose) for pre-septal and post- septal cellulitis (2 marks) Antibiotic (Dose and Route) Pre-septal cellulitis Post-septal cellulitis"},{"id":"d","label":"Part D","prompt":"List 4 complications of peri-orbital cellulitis (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>In the table below list 4 examination findings for each condition that may differentiate</td><td>pre-septal from post-septal cellulitis (8 marks)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Staph aureus</div><div class=\"answer-line\">• Haemophilus Influenzae type B (unvaccinated)</div><div class=\"answer-line\">• Strep species</div><div class=\"answer-line\">• Anaerobic bacteria in post septal</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List appropriate antibiotic therapy (include route and dose) for pre-septal and post-</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Orbital cellulitis</div><div class=\"answer-line\">• Cavernous sinus thrombosis</div><div class=\"answer-line\">• Osteomyelitis</div><div class=\"answer-line\">• Sepsis</div><div class=\"answer-line\">• Abscess</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 30 year old 90kg lady presents to your emergency department having taken a poly-\npharmacy overdose including panadeine forte, carbamazepine and temazepam. You are considering treating her with activated charcoal (AC).","parts":[{"id":"a","label":"Part A","prompt":"What dose would you use if you decided to administer AC (1 mark)"},{"id":"b","label":"Part B","prompt":"List 5 general contraindications for this therapy (5 marks)\nAfter a short period, she becomes drowsy, tachycardic (120 bpm) and hypotensive (85/43 mmHg). Further history reveals that she has taken up to 9g of carbamazepine."},{"id":"c","label":"Part C","prompt":"List 4 investigations that should be performed in this patient (4 marks)"},{"id":"d","label":"Part D","prompt":"List 5 clinical features you would expect from a significant carbamazepine overdose (5\nmarks)"},{"id":"e","label":"Part E","prompt":"During your management, the patient has a generalized tonic-clonic seizure. List 4 conditions that should be excluded (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• 50g (1g/kg in a paediatric patent)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Patient requiring active resuscitation</div><div class=\"answer-line\">• OD &gt; 1hr ago (controversial)</div><div class=\"answer-line\">• OD of non binding agent – (Metals/Hydrocarbon/Alcohols/Acids/Alkalis)</div><div class=\"answer-line\">• Aspiration risk - potential for seizures or decreasing LOC</div><div class=\"answer-line\">• Benign agent</div><div class=\"answer-line\">• Sub-toxic dose</div><div class=\"answer-line\">• Corrosive agent</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div><div class=\"answer-line\">• <strong>ECG </strong></div><div class=\"answer-line\">• <strong>BSL </strong></div><div class=\"answer-line\">• <strong>Paracetamol level </strong></div><div class=\"answer-line\">• HCG</div><div class=\"answer-line\">• Carbamazepine level</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">List 5 clinical features you would expect from a significant carbamazepine overdose (5</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">• CNS - decreased LOC/seizures/ataxia/nystagmus</div><div class=\"answer-line\">• CVS - hypotension/tachy-or-brady-arrhythmias, prolonged PR/QRS/QT, pulmonary</div><div class=\"answer-line\">oedema</div><div class=\"answer-line\">• Anti-cholinergic effects - retention/tachycardia/delirium etc</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">During your management, the patient has a generalized tonic-clonic seizure. List 4</div><div class=\"answer-line\">conditions that should be excluded (4 marks)</div><div class=\"answer-line\">• Hypoglycaemia</div><div class=\"answer-line\">• Hyponatraemia</div><div class=\"answer-line\">• Intracranial pathology</div><div class=\"answer-line\">• Pregnancy with eclampsia</div><div class=\"answer-line\">• Co-ingestant</div><div class=\"answer-line\">• Acute withdrawal</div><div class=\"answer-line\">NSW Fellowship Course - SAQ trial paper 2017.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
